DROP TRIGGER IF EXISTS recurring_invoice_templates_guard_update;
DROP TRIGGER IF EXISTS recurring_invoice_generations_no_update;
DROP TRIGGER IF EXISTS recurring_invoice_generations_no_delete;
DROP TABLE IF EXISTS recurring_invoice_templates_v3;
DROP TABLE IF EXISTS recurring_invoice_generations_v3_backup;
CREATE TABLE recurring_invoice_templates_v3 (id INTEGER PRIMARY KEY, name TEXT NOT NULL, interval TEXT NOT NULL CHECK(interval IN ('weekly','monthly','quarterly','yearly')), interval_count INTEGER NOT NULL DEFAULT 1 CHECK(interval_count BETWEEN 1 AND 120), delivery_channel TEXT NOT NULL DEFAULT 'manual' CHECK(delivery_channel IN ('manual','email','digisense')), first_issue_date TEXT NOT NULL, next_issue_date TEXT NOT NULL, payment_terms_days INTEGER NOT NULL DEFAULT 30 CHECK(payment_terms_days BETWEEN 0 AND 365), delivery_period_mode TEXT NOT NULL DEFAULT 'issue_month' CHECK(delivery_period_mode IN ('issue_month','interval_window','none')), payload_json TEXT NOT NULL, notes TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO recurring_invoice_templates_v3 (id,name,interval,interval_count,delivery_channel,first_issue_date,next_issue_date,payment_terms_days,delivery_period_mode,payload_json,notes,active,created_at) SELECT id,name,interval,1,'manual',first_issue_date,next_issue_date,payment_terms_days,delivery_period_mode,payload_json,notes,active,created_at FROM recurring_invoice_templates;
CREATE TABLE recurring_invoice_generations_v3_backup AS SELECT id,template_id,period_index,document_id,invoice_number,issue_date,delivery_period_start,delivery_period_end,created_at FROM recurring_invoice_generations;
DROP TABLE recurring_invoice_generations;
DROP TABLE recurring_invoice_templates;
ALTER TABLE recurring_invoice_templates_v3 RENAME TO recurring_invoice_templates;
CREATE TABLE recurring_invoice_generations (id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL REFERENCES recurring_invoice_templates(id), period_index INTEGER NOT NULL CHECK(period_index >= 0), document_id INTEGER NOT NULL REFERENCES documents(id), invoice_number TEXT NOT NULL, issue_date TEXT NOT NULL, delivery_period_start TEXT, delivery_period_end TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(template_id,period_index));
INSERT INTO recurring_invoice_generations (id,template_id,period_index,document_id,invoice_number,issue_date,delivery_period_start,delivery_period_end,created_at) SELECT id,template_id,period_index,document_id,invoice_number,issue_date,delivery_period_start,delivery_period_end,created_at FROM recurring_invoice_generations_v3_backup;
DROP TABLE recurring_invoice_generations_v3_backup;
CREATE INDEX idx_recurring_invoice_generations_template ON recurring_invoice_generations(template_id,period_index);
CREATE TABLE IF NOT EXISTS recurring_invoice_generation_claims (id INTEGER PRIMARY KEY, template_id INTEGER NOT NULL REFERENCES recurring_invoice_templates(id), period_index INTEGER NOT NULL CHECK(period_index >= 0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(template_id,period_index));
INSERT OR IGNORE INTO recurring_invoice_generation_claims(template_id,period_index) SELECT template_id,period_index FROM recurring_invoice_generations;
CREATE TABLE IF NOT EXISTS recurring_invoice_delivery_events (id INTEGER PRIMARY KEY, generation_id INTEGER NOT NULL REFERENCES recurring_invoice_generations(id), channel TEXT NOT NULL CHECK(channel IN ('email','digisense')), event_type TEXT NOT NULL CHECK(event_type IN ('attempted','acknowledged','accepted_pending','terminal_failed','uncertain','preflight_failed')), provider_id TEXT, message TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_recurring_invoice_delivery_events_generation ON recurring_invoice_delivery_events(generation_id,id DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_recurring_invoice_delivery_single_attempt ON recurring_invoice_delivery_events(generation_id) WHERE event_type = 'attempted';
CREATE TRIGGER recurring_invoice_templates_guard_update BEFORE UPDATE ON recurring_invoice_templates WHEN OLD.name != NEW.name OR OLD.interval != NEW.interval OR OLD.interval_count != NEW.interval_count OR OLD.delivery_channel != NEW.delivery_channel OR OLD.first_issue_date != NEW.first_issue_date OR OLD.payment_terms_days != NEW.payment_terms_days OR OLD.delivery_period_mode != NEW.delivery_period_mode OR OLD.payload_json != NEW.payload_json OR OLD.created_at != NEW.created_at OR NEW.next_issue_date < OLD.next_issue_date OR (OLD.active = 0 AND NEW.active = 1) BEGIN SELECT RAISE(ABORT, 'recurring invoice templates are append-only; only next_issue_date may advance and active may be retired'); END;
CREATE TRIGGER recurring_invoice_templates_no_delete BEFORE DELETE ON recurring_invoice_templates BEGIN SELECT RAISE(ABORT, 'recurring invoice templates are append-only; retire them with active = 0 instead'); END;
CREATE TRIGGER recurring_invoice_generations_no_update BEFORE UPDATE ON recurring_invoice_generations BEGIN SELECT RAISE(ABORT, 'recurring invoice generations are append-only audit links; issue a credit note on the generated invoice instead'); END;
CREATE TRIGGER recurring_invoice_generations_no_delete BEFORE DELETE ON recurring_invoice_generations BEGIN SELECT RAISE(ABORT, 'recurring invoice generations are append-only audit links; issue a credit note on the generated invoice instead'); END;
CREATE TRIGGER IF NOT EXISTS recurring_invoice_generation_claims_no_update BEFORE UPDATE ON recurring_invoice_generation_claims BEGIN SELECT RAISE(ABORT, 'recurring invoice generation claims are append-only'); END;
CREATE TRIGGER IF NOT EXISTS recurring_invoice_generation_claims_no_delete BEFORE DELETE ON recurring_invoice_generation_claims BEGIN SELECT RAISE(ABORT, 'recurring invoice generation claims are append-only'); END;
CREATE TRIGGER IF NOT EXISTS recurring_invoice_delivery_events_no_update BEFORE UPDATE ON recurring_invoice_delivery_events BEGIN SELECT RAISE(ABORT, 'recurring invoice delivery events are append-only'); END;
CREATE TRIGGER IF NOT EXISTS recurring_invoice_delivery_events_no_delete BEFORE DELETE ON recurring_invoice_delivery_events BEGIN SELECT RAISE(ABORT, 'recurring invoice delivery events are append-only'); END;
